'use strict';

// MODULES //

var verifyTransfer = require( '@data-apis/publish/verify-transfer' );


// VARIABLES //

var API_ROOT = 'https://api.github.com';
var MAX_API_BYTES = 1024 * 1024;


// FUNCTIONS //

/**
* Reads a bounded UTF-8 response body.
*
* @private
* @param {Response} response - response
* @returns {Promise<string>} decoded text
*/
async function responseText( response ) {
	var reader;
	var chunks = [];
	var total = 0;
	var item;

	if ( !response.body ) {
		return '';
	}
	reader = response.body.getReader();
	try {
		while ( true ) {
			item = await reader.read();
			if ( item.done ) {
				break;
			}
			total += item.value.byteLength;
			if ( total > MAX_API_BYTES ) {
				await reader.cancel();
				throw new Error( 'GitHub publication response exceeded the byte limit' );
			}
			chunks.push( Buffer.from( item.value ) );
		}
	} finally {
		reader.releaseLock();
	}
	return new TextDecoder( 'utf-8', { 'fatal': true } ).decode( Buffer.concat( chunks, total ) );
}

/**
* Reads a bounded response diagnostic.
*
* @private
* @param {Response} response - response
* @returns {Promise<string>} diagnostic
*/
async function responseDiagnostic( response ) {
	var text = await responseText( response );

	return text.replace( /[\u0000-\u001f\u007f]/g, ' ' ).slice( 0, 1000 );
}

/**
* Performs an authenticated GitHub Git Data API request.
*
* @private
* @param {string} route - API route
* @param {Object} options - request options
* @returns {Promise<Object>} parsed response
*/
async function githubRequest( route, options ) {
	var response = await ( options.fetchImpl || globalThis.fetch )( API_ROOT + route, {
		'method': options.method || 'GET',
		'headers': {
			'accept': 'application/vnd.github+json',
			'authorization': 'Bearer ' + options.token,
			'content-type': 'application/json',
			'user-agent': 'array-api-compliance-publisher',
			'x-github-api-version': '2022-11-28'
		},
		'body': options.body ? JSON.stringify( options.body ) : undefined,
		'redirect': 'error',
		'signal': AbortSignal.timeout( 30000 )
	} );

	if ( !response.ok ) {
		throw new Error( 'GitHub publication request failed with HTTP ' + response.status + ': ' + await responseDiagnostic( response ) );
	}
	return response.status === 204 ? {} : JSON.parse( await responseText( response ) );
}

/**
* Tests whether a branch name is safe for Git reference publication.
*
* @private
* @param {string} branch - branch name
* @returns {boolean} result
*/
function validBranch( branch ) {
	return typeof branch === 'string' && branch.length > 0 && branch.length <= 255 &&
		!branch.startsWith( '/' ) && !branch.endsWith( '/' ) && !branch.endsWith( '.' ) &&
		branch !== '@' && !branch.includes( '..' ) && !branch.includes( '//' ) && !branch.includes( '@{' ) &&
		!/[\u0000-\u0020~^:?*\[\]\\\u007f]/.test( branch ) && !branch.split( '/' ).some( function invalidPart( part ) {
		return part.startsWith( '.' ) || part.endsWith( '.lock' );
	} );
}

/**
* Encodes a Git reference path for the REST API.
*
* @private
* @param {string} branch - branch name
* @returns {string} encoded ref
*/
function encodedBranch( branch ) {
	return branch.split( '/' ).map( encodeURIComponent ).join( '/' );
}


// MAIN //

/**
* Publishes validated harvest files with an atomic non-force ref update.
*
* @param {Object} options - publication options
* @returns {Promise<Object>} publication result
*/
async function run( options ) {
	var verified;
	var manifest;
	var repository = options.repository;
	var branch = options.branch;
	var files;
	var records;
	var ref;
	var parentCommit;
	var treeEntries = [];
	var commit;
	var blob;
	var tree;
	var idx;

	if ( !/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test( repository || '' ) ) {
		throw new Error( 'Invalid publication repository' );
	}
	if ( !validBranch( branch ) || !options.token ) {
		throw new Error( 'Publication branch and token are required' );
	}
	verified = await verifyTransfer( options );
	manifest = verified.manifest;
	files = verified.files;
	records = verified.records;
	if ( records.length === 0 ) {
		return {
			'published': false,
			'commitSha': undefined
		};
	}
	ref = await githubRequest( '/repos/' + repository + '/git/ref/heads/' + encodedBranch( branch ), {
		'token': options.token,
		'fetchImpl': options.fetchImpl
	} );
	if ( !ref.object || ref.object.sha !== manifest.base_sha ) {
		throw new Error( 'Default branch advanced after harvesting; refusing non-atomic publication' );
	}
	parentCommit = await githubRequest( '/repos/' + repository + '/git/commits/' + manifest.base_sha, {
		'token': options.token,
		'fetchImpl': options.fetchImpl
	} );
	for ( idx = 0; idx < files.length; idx += 1 ) {
		blob = await githubRequest( '/repos/' + repository + '/git/blobs', {
			'method': 'POST',
			'token': options.token,
			'fetchImpl': options.fetchImpl,
			'body': {
				'content': files[ idx ].bytes.toString( 'base64' ),
				'encoding': 'base64'
			}
		} );

		treeEntries.push( {
			'path': files[ idx ].path,
			'mode': '100644',
			'type': 'blob',
			'sha': blob.sha
		} );
	}
	tree = await githubRequest( '/repos/' + repository + '/git/trees', {
		'method': 'POST',
		'token': options.token,
		'fetchImpl': options.fetchImpl,
		'body': {
			'base_tree': parentCommit.tree.sha,
			'tree': treeEntries
		}
	} );
	commit = await githubRequest( '/repos/' + repository + '/git/commits', {
		'method': 'POST',
		'token': options.token,
		'fetchImpl': options.fetchImpl,
		'body': {
			'message': 'chore(data): harvest ' + records.length + ' compliance report' + ( records.length === 1 ? '' : 's' ),
			'tree': tree.sha,
			'parents': [manifest.base_sha]
		}
	} );
	await githubRequest( '/repos/' + repository + '/git/refs/heads/' + encodedBranch( branch ), {
		'method': 'PATCH',
		'token': options.token,
		'fetchImpl': options.fetchImpl,
		'body': {
			'sha': commit.sha,
			'force': false
		}
	} );
	return {
		'published': true,
		'commitSha': commit.sha
	};
}


// EXPORTS //

module.exports = run;
